const il = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jerusalem' }));
const iso = il.getFullYear() + '-' + String(il.getMonth() + 1).padStart(2, '0') + '-' + String(il.getDate()).padStart(2, '0');
const items = ($input.first() && $input.first().json && $input.first().json.items) || [];
const holidayDates = items.filter(it => it.yomtov === true && it.date).map(it => it.date.slice(0, 10));
if (holidayDates.includes(iso)) return [];
return [{ json: { ok: true, checkedDate: iso, holidayDates } }];

function isTeddy(name) {
  return name.includes('בית') || (name.includes('הפועל') && name.includes('ירושלים'));
}
const strip = (t) => t.replace(/<[^>]*>?/gm, '').trim();
function mapEvent(n) {
  if (/premier/i.test(n)) return 'ליגת העל';
  if (/cup/i.test(n)) return 'גביע המדינה';
  if (/super/i.test(n)) return 'הסופר קאפ';
  return n || 'משחק בטדי';
}
const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const j = item.json || {};

  // --- מקור A: API-Football (venue=866 = טדי) — כל משחק, כל הקבוצות ---
  if (Array.isArray(j.response)) {
    for (const f of j.response) {
      const v = (f.fixture && f.fixture.venue && f.fixture.venue.name) || '';
      if (!/teddy|malcha/i.test(v)) continue;
      const iso = f.fixture && f.fixture.date; if (!iso) continue;
      const Y = iso.slice(0, 4), M = iso.slice(5, 7), D = iso.slice(8, 10);
      const date = D + '.' + M + '.' + Y.slice(2);
      const time = iso.slice(11, 16);
      const host = (f.teams && f.teams.home && f.teams.home.name) || '';
      const guest = (f.teams && f.teams.away && f.teams.away.name) || '';
      if (!host || !time) continue;
      const key = date + '|' + time;
      if (seen.has(key)) continue;
      seen.add(key);
      results.push({ json: { eventName: mapEvent(f.league && f.league.name), hostTeam: host, opponent: guest, date, time, day: '', source: 'apifootball' } });
    }
    continue;
  }

  // --- מקור B: sport5 (דפי קבוצה, HTML) — דיירות טדי בלבד ---
  const html = j.data;
  if (!html) continue;
  const rows = html.match(/<tr[\s\S]*?<\/tr>/gi) || [];
  for (const row of rows) {
    if (row.includes('<th')) continue;
    if (row.includes('סקירה') || row.includes('class="link"')) continue;
    const cells = row.match(/<td[\s\S]*?<\/td>/gi);
    if (!cells || cells.length < 4) continue;
    const links = cells[0].match(/<a[^>]*>(.*?)<\/a>/gi);
    if (!links || links.length < 2) continue;
    const host = strip(links[0]);
    const guest = strip(links[1]);
    if (!isTeddy(host)) continue;
    const time = strip(cells[2]);
    const date = strip(cells[3]);
    if (!date || !time) continue;
    const key = date + '|' + time;
    if (seen.has(key)) continue;
    seen.add(key);
    const isDerby = isTeddy(host) && isTeddy(guest);
    results.push({ json: { eventName: isDerby ? 'דרבי ירושלים' : 'ליגת העל', hostTeam: host, opponent: guest, date, time, day: strip(cells[1]), source: 'sport5' } });
  }
}
return results;

const now = new Date();
const MS_DAY = 86400000;
const DAYS = [
  { n: 'ראשון', w: false }, { n: 'שני', w: false }, { n: 'שלישי', w: false },
  { n: 'רביעי', w: false }, { n: 'חמישי', w: false }, { n: 'שישי', w: true }, { n: 'שבת', w: true }
];
const TRAFFIC_START_HOURS = 3.5, SAFETY_BUFFER_MIN = 30;
const WALK_MIN = 15, TRAIN_MIN = 50, BUS_MIN = 30;
const BEFORE_MS = (TRAFFIC_START_HOURS * 60 + SAFETY_BUFFER_MIN) * 60000;

let holidaySet = new Set();
try { holidaySet = new Set((($('שער שבת/חג').first() || {}).json || {}).holidayDates || []); } catch (e) {}

const pad = (n) => String(n).padStart(2, '0');
function parseDT(d, t) { const [D, M, Y] = d.split('.').map(Number); const [h, m] = t.split(':').map(Number); return new Date(2000 + Y, M - 1, D, h, m); }
function fmt(dt) { return dt.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' }); }
function floor30(dt) { const x = new Date(dt); x.setMinutes(x.getMinutes() >= 30 ? 30 : 0, 0, 0); return x; }

const results = [];
for (const item of $input.all()) {
  const g = item.json;
  if (!g.date || !g.time) continue;
  const ko = parseDT(g.date, g.time);
  if (!ko || ko < now) continue;
  const dow = ko.getDay();
  const di = DAYS[dow];
  const [D, M, Y] = g.date.split('.').map(Number);
  const gISO = (2000 + Y) + '-' + pad(M) + '-' + pad(D);
  const isYomtov = holidaySet.has(gISO);
  const diffDays = Math.ceil((ko - now) / MS_DAY);
  const level = diffDays <= 1 ? 'red' : diffDays <= 4 ? 'yellow' : 'green';

  const noTrain = di.w || isYomtov;
  const mode = noTrain ? 'car' : 'train';
  const noTrainReason = isYomtov ? 'חג' : dow === 6 ? 'שבת' : dow === 5 ? 'ערב שבת' : '';

  const leaveBy = fmt(new Date(ko.getTime() - BEFORE_MS));
  let trainTime = '', trainArrivalTime = '', arrivalTeddyTime = '', leaveWorkTime = '';
  if (mode === 'train') {
    const board = floor30(new Date(ko.getTime() - BEFORE_MS - (BUS_MIN + TRAIN_MIN) * 60000));
    trainTime = fmt(board);
    trainArrivalTime = fmt(new Date(board.getTime() + TRAIN_MIN * 60000));
    arrivalTeddyTime = fmt(new Date(board.getTime() + (TRAIN_MIN + BUS_MIN) * 60000));
    leaveWorkTime = fmt(new Date(board.getTime() - WALK_MIN * 60000));
  }

  results.push({ json: {
    eventName: g.eventName || 'ליגת העל', hostTeam: g.hostTeam, opponent: g.opponent,
    date: g.date, time: g.time, dayName: di.n, isWeekend: di.w, isYomtov,
    level, mode, noTrainReason, leaveBy,
    escapeTime: leaveWorkTime || leaveBy,
    trainTime, trainArrivalTime, arrivalTeddyTime, leaveWorkTime,
    kickoffTimestamp: ko.getTime()
  }});
}
results.sort((a, b) => a.json.kickoffTimestamp - b.json.kickoffTimestamp);
return results;

const items = $input.all();
const now = new Date();
const MS_DAY = 86400000;
const WAZE = 'https://waze.com/ul?ll=31.7698,35.1934&navigate=yes';
const pad = (n) => String(n).padStart(2, '0');
function weatherAt(dateStr, timeStr) {
  try {
    const w = (($('מזג אוויר').first() || {}).json) || {};
    const h = w.hourly; if (!h || !h.time) return null;
    const [D, M, Y] = dateStr.split('.').map(Number);
    const key = (2000 + Y) + '-' + pad(M) + '-' + pad(D) + 'T' + pad(parseInt(timeStr, 10)) + ':00';
    const idx = h.time.indexOf(key);
    if (idx < 0) return null;
    return { t: Math.round(h.temperature_2m[idx]), rain: h.precipitation_probability[idx] };
  } catch (e) { return null; }
}
function weatherLine(m) {
  const w = weatherAt(m.date, m.time);
  if (!w) return '';
  let s = '🌡️ ' + w.t + '°';
  if (w.rain != null) s += '  ·  🌧️ ' + w.rain + '%' + (w.rain >= 50 ? ' (קח מטרייה)' : '');
  return s;
}
if (!items.length) {
  return [{ json: { text: '🏟️ *אצטדיון טדי — התראות תנועה*\n────────────────\n🟢 אין משחקים קרובים בטדי.\nהדרך פנויה 🚗' } }];
}
const L = ['🏟️ *אצטדיון טדי — התראות תנועה*'];
for (let i = 0; i < Math.min(items.length, 3); i++) {
  const m = items[i].json;
  const dd = Math.ceil((m.kickoffTimestamp - now) / MS_DAY);
  const icon = m.level === 'red' ? '🔴' : m.level === 'yellow' ? '🟠' : '🟢';
  const cd = dd <= 0 ? 'היום' : dd === 1 ? 'מחר' : 'בעוד ' + dd + ' ימים';
  L.push('');
  L.push('━━━━━━━━━━━━━━');
  if (i === 0) {
    L.push(icon + ' *' + m.hostTeam + ' נגד ' + m.opponent + '*');
    L.push('📅 ' + m.dayName + ', ' + m.date + '  |  ⏰ ' + m.time);
    L.push('🏆 ' + m.eventName + '  ·  ⏳ ' + cd);
    const wl = weatherLine(m); if (wl) L.push(wl);
    if (m.mode === 'car') {
      L.push('🚆 אין רכבת (' + (m.noTrainReason || 'סופ״ש') + ')');
      L.push('🚗 סע ברכב — צא *עד ' + m.leaveBy + '*');
    } else {
      const tag = m.level === 'red' ? '⚠️ *עומס כבד צפוי!*' : m.level === 'yellow' ? 'ℹ️ צפוי עומס ביום המשחק' : 'ℹ️ לתכנון מוקדם';
      L.push(tag);
      L.push('🚂 תפוס רכבת *' + m.trainTime + '* מתל אביב');
      L.push('   ↳ הגעה לטדי בערך ' + m.arrivalTeddyTime + '  (יציאה מהעבודה ' + m.leaveWorkTime + ')');
    }
    L.push('🗺️ [ניווט לטדי ב-Waze](' + WAZE + ')');
  } else {
    L.push(icon + ' *' + m.date + ' ' + m.time + '* — ' + m.hostTeam + ' נגד ' + m.opponent);
    const extra = m.mode === 'car' ? '🚗 רכב (' + (m.noTrainReason || 'סופ״ש') + ')' : '🚂 רכבת ' + m.trainTime;
    L.push('🏆 ' + m.eventName + '  ·  ⏳ ' + cd + '  ·  ' + extra);
  }
}
L.push('');
L.push('📍 אצטדיון טדי קולק, ירושלים');
return [{ json: { text: L.join('\n') } }];

const games = $input.all().map(i => i.json);
const now = new Date();
const MS_DAY = 86400000;
const WAZE = 'https://waze.com/ul?ll=31.7698,35.1934&navigate=yes';
