}
function card(g) {
  const dd = Math.ceil((g.kickoffTimestamp - now) / MS_DAY);
  const cd = dd <= 0 ? 'היום' : dd === 1 ? 'מחר' : 'בעוד ' + dd + ' ימים';
  const icon = g.level === 'red' ? '🔴' : g.level === 'yellow' ? '🟠' : '🟢';
  const txt = g.level === 'red' ? 'קרוב מאוד — עומס צפוי' : g.level === 'yellow' ? 'מתקרב — כדאי לתכנן' : 'רחוק — לידיעה';
  const bc = g.level === 'red' ? '#DC2626' : g.level === 'yellow' ? '#D97706' : '#16A34A';
  const w = weatherAt(g.date, g.time);
  const wHtml = w ? '<span style="color:#6B7280;">🌡️ ' + w.t + '°' + (w.rain != null ? '  ·  🌧️ ' + w.rain + '%' + (w.rain >= 50 ? ' (קח מטרייה)' : '') : '') + '</span>' : '';
  let plan;
  if (g.mode === 'car') {
    plan = '<div style="margin-top:12px;background:#FEF3F2;border-radius:8px;padding:12px 14px;font-size:14px;line-height:1.9;">'
      + '🚆 <strong>אין רכבת</strong> (' + (g.noTrainReason || 'סופ״ש') + ') — רכבת ישראל לא פעילה'
      + '<br>🚗 סע ברכב — צא <strong>עד ' + g.leaveBy + '</strong>'
      + '</div>';
