  return '<div style="background:white;border-radius:12px;border-right:5px solid ' + bc + ';border-top:1px solid #E5E7EB;border-bottom:1px solid #E5E7EB;border-left:1px solid #E5E7EB;padding:18px;margin-bottom:16px;direction:rtl;text-align:right;">'
