}
const html = '<!DOCTYPE html><html lang="he"><head><meta charset="UTF-8"><title>התראות טדי</title></head>'
  + '<body style="margin:0;padding:0;background:#F6F7F9;font-family:Arial,sans-serif;">'
  + '<div style="padding:32px 0;"><div style="max-width:600px;margin:auto;background:white;border-radius:16px;padding:24px;border:1px solid #E5E7EB;direction:rtl;text-align:right;">'
  + '<h1 style="margin:0;text-align:center;font-size:26px;">🏟️ התראות תנועה — אצטדיון טדי</h1>'
  + '<p style="margin:8px 0 20px;text-align:center;font-size:13px;color:#4B5563;">כל האירועים הקרובים בטדי · מתי לתפוס רכבת ומתי לצאת מהעבודה</p>'
  + games.map(card).join('')
  + '<p style="margin-top:14px;text-align:center;font-size:12px;color:#9CA3AF;">🟢 רחוק · 🟠 מתקרב · 🔴 קרוב מאוד</p>'
  + '</div></div></body></html>';
return [{ json: { html } }];
